css:
/* =========================================================
   GENERAL — RESET
   ========================================================= */

* {
    box-sizing: border-box;
    -webkit-print-color-adjust: exact !important;
    print-color-adjust: exact !important;
}

.print-format table,
.print-format tr,
.print-format td,
.print-format th {
    border: none !important;
    border-collapse: collapse !important;
    border-spacing: 0 !important;
    padding: 0 !important;
    margin: 0 !important;
    vertical-align: top !important;
}

body {
    margin: 0;
    padding: 0;
    font-family: "Segoe UI", Arial, sans-serif;
    font-size: 10px;
    color: #1f2937;
    line-height: 1.25;
}


/* =========================================================
   SECTION HEADING
   ========================================================= */

.section-heading {
    margin-top: 22px !important;
    margin-bottom: 14px !important;
    font-size: 13px !important;
    font-weight: 700 !important;
    letter-spacing: 0.5px;
    color: #374151;
}


/* =========================================================
   EMPLOYEE SUMMARY
   ========================================================= */

.emp-summary-table {
    width: 100%;
    table-layout: fixed;
    margin-bottom: 22px !important;
}

.left-col {
    width: 62%;
    padding-right: 18px !important;
    vertical-align: top !important;
}

.right-col {
    width: 38%;
    padding-left: 8px !important;
    vertical-align: top !important;
}

.summary-table {
    width: 100%;
}

.summary-table td {
    padding: 7px 0 !important;
    font-size: 13px !important;
    text-align: left !important;
    vertical-align: middle !important;
}

.summary-table td.label {
    width: 105px;
    font-weight: 600 !important;
    color: #374151 !important;
    white-space: nowrap;
    background: none !important;
}

.summary-table td:nth-child(2) {
    width: 12px;
    text-align: center !important;
    color: #6b7280 !important;
}

.summary-table td:nth-child(3) {
    color: #111827 !important;
    font-weight: 400 !important;
    padding-left: 6px !important;
}


/* =========================================================
   NET PAY CARD
   ========================================================= */

.print-format .net-pay-wrapper {
    border: 1px solid #b7e4c7 !important;
    border-radius: 8px !important;
    overflow: hidden !important;
}

.print-format .net-pay-card {
    width: 100%;
    background-color: #e9f9ee !important;
}

.print-format .net-pay-card td {
    text-align: left !important;
    background-color: #e9f9ee !important;
    padding: 0 0 0 22px !important;
}

/* Green accent bar — upper section only (amount, label, divider). Stops before Paid Days/LOP Days. */
.print-format .net-pay-card tr:nth-child(-n+3) td {
    border-left: 4px solid #16a34a !important;
    padding-left: 18px !important;
}

.print-format .net-pay-card tr:first-child td {
    padding-top: 14px !important;
}

.net-pay-amount {
    font-size: 20px !important;
    font-weight: 700 !important;
    color: #111827 !important;
}

/* Total Net Pay */
.print-format .net-pay-card tr:nth-child(2) td.net-pay-label {
    font-size: 10px !important;
    font-weight: 700 !important;
    color: #6b7280 !important;
    padding-bottom: 10px !important;
}

/* Divider */
.print-format .net-pay-divider td {
    padding: 0 18px !important;
}

.print-format .net-pay-divider hr {
    display: block !important;
    margin: 0 !important;
    border: 0 !important;
    border-top: 1px dashed #7fbf9e !important;
    height: 0;
}

/* Paid Days / LOP Days — white section, no green fill */
.days-row {
    font-size: 11px !important;
    color: #4b5563 !important;
    padding: 5px 22px !important;
}

.net-pay-card tr:nth-last-child(2) td,
.net-pay-card tr:last-child td {
    background: #ffffff !important;
    padding: 6px 22px !important;
}

.print-format .net-pay-card tr:last-child td {
    padding-bottom: 14px !important;
}


/* =========================================================
   LOCATION + PAN
   ========================================================= */

.print-format .location-table {
    width: 100%;
    margin-top: 18px !important;
    margin-bottom: 26px !important;
    padding: 14px 0 !important;
    border-top: 1px dashed #9ca3af !important;
    border-bottom: 1px dashed #9ca3af !important;
}

.location-table td {
    width: 50%;
    padding: 8px 0 !important;
    font-size: 13px !important;
}

.location-table td:last-child {
    padding-left: 20px !important;
}

.location-table span.label {
    font-weight: 600 !important;
    color: #374151 !important;
    background: none !important;
    border: none !important;
    padding: 0 !important;
    display: inline !important;
    font-size: 13px !important;
}


/* =========================================================
   EARNINGS / DEDUCTIONS TABLE
   ========================================================= */

.print-format .earn-ded-wrapper {
    border: 1px solid #9ca3af !important;
    border-radius: 10px !important;
    overflow: hidden !important;
    margin-bottom: 30px !important;
}

.print-format .earn-ded-table {
    width: 100%;
    table-layout: fixed;
}

/* Column widths */
.earn-ded-table td:nth-child(1) {
    width: 32%;
}

.earn-ded-table td:nth-child(2) {
    width: 18%;
}

.earn-ded-table td:nth-child(3) {
    width: 32%;
}

.earn-ded-table td:nth-child(4) {
    width: 18%;
}

/* (outer border now handled by .earn-ded-wrapper) */


/* =========================================================
   EARNINGS / DEDUCTIONS HEADER — no fill, just underline
   ========================================================= */

.print-format .earn-ded-table .ed-head td {
    padding: 10px 12px !important;
    background: none !important;
    border-top: 1px solid #9ca3af !important;
    border-bottom: 1px solid #9ca3af !important;
    font-size: 13px !important;
    font-weight: 700 !important;
    color: #374151 !important;
    letter-spacing: 0.4px;
}

.earn-ded-table .ed-head td:nth-child(2),
.earn-ded-table .ed-head td:nth-child(4) {
    text-align: right !important;
}


/* =========================================================
   NORMAL EARNINGS / DEDUCTIONS ROWS — no fill
   ========================================================= */

.print-format .earn-ded-table tr:not(.ed-head):not(.ed-total) td {
    padding: 11px 12px !important;
    font-size: 13px !important;
    font-weight: 400 !important;
    color: #374151 !important;
    background: none !important;
}

/* Salary component names only — Basic, HRA, etc. */
.print-format .earn-ded-table tr:not(.ed-head):not(.ed-total) td:nth-child(1),
.print-format .earn-ded-table tr:not(.ed-head):not(.ed-total) td:nth-child(3) {
    font-weight: 700 !important;
}

/* Amount columns — no vertical divider between Earnings and Deductions */
.earn-ded-table tr td:nth-child(2),
.earn-ded-table tr td:nth-child(4) {
    text-align: right !important;
    white-space: nowrap;
}


/* =========================================================
   FINAL TOTAL ROW — only this row shaded
   ========================================================= */

.print-format .earn-ded-table .ed-total td {
    padding: 10px 12px !important;
    background-color: #f3f4f6 !important;
    border-top: 1px solid #9ca3af !important;
    font-size: 13px !important;
    font-weight: 700 !important;
    color: #1f2937 !important;
}


/* =========================================================
   PDF PRINT CONTROL
   ========================================================= */

@media print {

    body {
        margin: 0;
        padding: 0;
    }

    .emp-summary-table,
    .location-table,
    .earn-ded-table {
        page-break-inside: avoid;
    }

    .earn-ded-table tr {
        page-break-inside: avoid;
    }
}
